def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    bg = max(set(v for row in g for v in row), key=lambda x: sum(row.count(x) for row in g))
    pairs = set()

    for r in range(h):
        for c in range(w):
            color = g[r][c]
            if color == bg:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                rr, cc = r + dr, c + dc
                if 0 <= rr < h and 0 <= cc < w and g[rr][cc] == color:
                    pairs.add((color, r, c, dr, dc))

    for color, r, c, dr, dc in pairs:
        for sr, sc in ((-dr, -dc), (dr, dc)):
            rr, cc = r, c
            while 0 <= rr + sr < h and 0 <= cc + sc < w:
                rr += sr
                cc += sc
                if g[rr][cc] != bg and g[rr][cc] != color:
                    break
                g[rr][cc] = color
    return g
